{
  "name": "优傲机械臂夹爪系统",
  "name_en": "Universal Robots Arm with Gripper",
  "manufacturer": "Universal Robots",
  "description": "用于实验室自动化的机械臂与夹爪控制系统，可进行笛卡尔空间直线运动、位置等待以及夹爪开合，适合样品抓取、转移和放置等操作。",
  "description_en": "A laboratory automation robotic arm and gripper system for Cartesian linear motion, motion completion waiting, and gripper open/close control, suitable for sample pick-and-place, transfer, and handling tasks.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化机械臂与夹爪控制会话。",
      "description_en": "Initialize the robot arm and gripper control session."
    },
    {
      "action_name": "auto-setp_to_list",
      "description": "将运动设定点转换为列表格式。",
      "description_en": "Convert a motion setpoint to list format."
    },
    {
      "action_name": "auto-list_to_setp",
      "description": "将列表转换为运动设定点格式。",
      "description_en": "Convert a list to motion setpoint format."
    },
    {
      "action_name": "auto-wait",
      "description": "等待机械臂运动到目标笛卡尔位置附近后返回。",
      "description_en": "Wait until the robot reaches near the target Cartesian position."
    },
    {
      "action_name": "auto-movel",
      "description": "控制机械臂沿直线运动到指定笛卡尔位置。",
      "description_en": "Move the robot linearly to the specified Cartesian position."
    },
    {
      "action_name": "auto-open_gripper",
      "description": "打开夹爪。",
      "description_en": "Open the gripper."
    },
    {
      "action_name": "auto-close_gripper",
      "description": "闭合夹爪。",
      "description_en": "Close the gripper."
    },
    {
      "action_name": "auto-angle_antipodal_grasp",
      "description": "根据给定抓取角度计算对握抓取姿态参数。",
      "description_en": "Calculate antipodal grasp orientation parameters from a given grasp angle."
    }
  ],
  "tag_hints": [
    "Universal Robots",
    "RTDE motion control",
    "robotic arm",
    "Cartesian linear motion",
    "gripper control",
    "pick-and-place automation",
    "antipodal grasp planning"
  ]
}

